class _MinesState extends State<_Mines>{final r=Random();late List<bool> mine;late List<int> nums;Set<int> open={},flags={};bool lost=false,won=false;@override void initState(){super.initState();reset();}void reset(){mine=List.filled(81,false);nums=List.filled(81,0);open={};flags={};lost=false;won=false;int n=0;while(n<11){final i=r.nextInt(81);if(!mine[i]){mine[i]=true;n++;}}for(int i=0;i<81;i++){if(mine[i])continue;final x=i%9,y=i~/9;int z=0;for(int yy=-1;yy<=1;yy++)for(int xx=-1;xx<=1;xx++){final nx=x+xx,ny=y+yy;if(nx>=0&&nx<9&&ny>=0&&ny<9&&mine[ny*9+nx])z++;}nums[i]=z;}}void reveal(int i){if(lost||won||flags.contains(i)||open.contains(i))return;if(mine[i]){setState((){lost=true;open=Set.from(List.generate(81,(j)=>j));});return;}setState(()=>open.add(i));if(open.length>=70)won=true;}Widget build(BuildContext c)=>_Shell(title:'Minesweeper',subtitle:'Hazard Command • 11 mines • ${flags.length} flags',accent:Color(0xFFF97316),onReset:()=>setState(reset),child:_World(Padding(padding:EdgeInsets.all(14),child:GridView.builder(gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:9,crossAxisSpacing:3,mainAxisSpacing:3),itemCount:81,itemBuilder:(_,i){final shown=open.contains(i);return GestureDetector(onTap:()=>reveal(i),onLongPress:(){if(open.contains(i))return;setState(()=>flags.contains(i)?flags.remove(i):flags.add(i));},child:Container(decoration:BoxDecoration(color:shown?Colors.white.withOpacity(.06):Color(0xFF182233),borderRadius:BorderRadius.circular(6),border:Border.all(color:Colors.white10)),child:Center(child:flags.contains(i)?Icon(Icons.flag_rounded,color:Color(0xFFF97316),size:17):shown?(mine[i]?Icon(Icons.warning_rounded,color:Colors.redAccent,size:18):Text('${nums[i]}',style:TextStyle(fontWeight:FontWeight.w900,color: nums[i]==0?Colors.transparent:(nums[i]==1?Color(0xFF22D3EE):nums[i]==2?Color(0xFF22C55E):nums[i]==3?Color(0xFFFBBF24):Color(0xFFF97316))))):null)));})));}

