class _SimonState extends State<_Simon>{final r=Random();List<int> seq=[];int at=0,flash=-1;bool accepting=false;int score=0;@override void initState(){super.initState();start();}void start(){seq=[];at=0;score=0;next();}void next(){seq.add(r.nextInt(4));playSequence();}Future<void> playSequence()async{setState(()=>accepting=false);for(final x in seq){if(!mounted)return;setState(()=>flash=x);await Future.delayed(Duration(milliseconds:350));if(!mounted)return;setState(()=>flash=-1);await Future.delayed(Duration(milliseconds:120));}if(mounted)setState(()=>accepting=true);}void tap(int x){if(!accepting)return;if(seq[at]!=x){setState(()=>accepting=false);Future.delayed(Duration(milliseconds:500),(){if(mounted)start();});return;}at++;if(at==seq.length){score++;at=0;Future.delayed(Duration(milliseconds:300),(){if(mounted)next();});}}@override Widget build(BuildContext c)=>_Shell(title:'Simon Says',subtitle:'Pulse Memory • streak $score',accent:Color(0xFF14B8A6),onReset:()=>setState(start),child:_World(Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(flash>=0?'WATCH':'YOUR TURN',style:TextStyle(fontSize:14,fontWeight:FontWeight.w900,color:Colors.white54,letterSpacing:2)),SizedBox(height:18),Padding(padding:EdgeInsets.all(22),child:GridView.count(shrinkWrap:true,crossAxisCount:2,crossAxisSpacing:14,mainAxisSpacing:14,children:[for(int i=0;i<4;i++)GestureDetector(onTap:()=>tap(i),child:AnimatedContainer(duration:Duration(milliseconds:100),decoration:BoxDecoration(color:[Color(0xFF22C55E),Color(0xFFF97316),Color(0xFF3B82F6),Color(0xFFD946EF)][i].withOpacity(flash==i?.95:.45),borderRadius:BorderRadius.circular(30),boxShadow:[if(flash==i)BoxShadow(color:[Color(0xFF22C55E),Color(0xFFF97316),Color(0xFF3B82F6),Color(0xFFD946EF)][i].withOpacity(.35),blurRadius:30)])),child:Icon([Icons.circle,Icons.square_rounded,Icons.change_history_rounded,Icons.diamond_rounded][i],size:36,color:Colors.white70))))]))]));}

