class _ColorStackState extends State<_ColorStack>{final r=Random();late List<List<int>> tubes;int? selected;int moves=0;@override void initState(){super.initState();reset();}void reset(){tubes=[[0,1,2,3],[0,1,2,3],[4,5,6,7],[4,5,6,7],[],[]];tubes=tubes.map((x)=>x.toList()).toList();for(final x in tubes)x.shuffle(r);selected=null;moves=0;}bool solved(List<int>x)=>x.isEmpty||(x.length==4&&x.every((v)=>v==x.first));void tap(int i){if(selected==null){if(tubes[i].isNotEmpty&&!solved(tubes[i]))setState(()=>selected=i);return;}if(i==selected){setState(()=>selected=null);return;}final from=tubes[selected!],to=tubes[i];if(to.length>=4){setState(()=>selected=null);return;}final color=from.last;int count=0;for(int k=from.length-1;k>=0&&from[k]==color;k--)count++;if(to.isNotEmpty&&to.last!=color){setState(()=>selected=null);return;}final take=min(count,4-to.length);setState((){for(int k=0;k<take;k++)to.add(from.removeLast());moves++;selected=null;});}Widget build(BuildContext c)=>_Shell(title:'Color Stack',subtitle:'Chromatic Lab • $moves moves',accent:Color(0xFF6366F1),onReset:()=>setState(reset),child:_World(Center(child:Wrap(alignment:WrapAlignment.center,spacing:18,runSpacing:22,children:[for(int i=0;i<tubes.length;i++)GestureDetector(onTap:()=>tap(i),child:AnimatedContainer(duration:Duration(milliseconds:180),width:55,height:170,padding:EdgeInsets.all(6),decoration:BoxDecoration(color:selected==i?Color(0xFF6366F1).withOpacity(.16):Colors.white.withOpacity(.035),borderRadius:BorderRadius.circular(22),border:Border.all(color:selected==i?Color(0xFF818CF8):Colors.white10)),child:Column(mainAxisAlignment:MainAxisAlignment.end,children:[for(final v in tubes[i])Container(height:36,margin:EdgeInsets.only(bottom:3),decoration:BoxDecoration(color:[Color(0xFF22D3EE),Color(0xFFF59E0B),Color(0xFFEC4899),Color(0xFF22C55E),Color(0xFFA78BFA),Color(0xFFF97316),Color(0xFF60A5FA),Color(0xFFF43F5E)][v],borderRadius:BorderRadius.circular(11))),]))]))));}
